//============================================================================
//  V60 CMPC/MOVC fill & stop variants + exact tail registers (op7a.hxx).
//  Auto-generated by scratchpad/gen_strfs_tb.py; expectations come from the
//  str_oracle.py mirror of MAME opCMPSTRB/H and opMOVSTRU*/D* (bFill,bStop).
//============================================================================
`timescale 1ns/1ps
module tb_v60_strfs;
reg clk = 0, rst = 1;
always #10 clk = ~clk;
wire        c_req, c_we, c_ack;
wire [31:0] c_addr, c_wdata, c_rdata;
wire [1:0]  c_size;
wire        m_req, m_we, m_ack;
wire [23:1] m_addr;
wire [15:0] m_wdata, m_rdata;
wire [1:0]  m_be;
s32_v60 #(.START_PC(32'h0)) cpu (
    .clk(clk), .ce(1'b1), .rst(rst),
    .if_req(), .if_addr(), .if_data(64'd0), .if_ack(1'b0),
    .bus_req(c_req), .bus_we(c_we), .bus_addr(c_addr), .bus_size(c_size),
    .bus_wdata(c_wdata), .bus_rdata(c_rdata), .bus_ack(c_ack),
    .irq_n(1'b1), .irq_vector(8'h00), .irq_ack(), .nmi_n(1'b1));
s32_v60_bus adapter (
    .clk(clk), .ce(1'b1), .rst(rst),
    .c_req(c_req), .c_we(c_we), .c_addr(c_addr), .c_size(c_size),
    .c_wdata(c_wdata), .c_rdata(c_rdata), .c_ack(c_ack),
    .m_req(m_req), .m_we(m_we), .m_addr(m_addr), .m_wdata(m_wdata),
    .m_be(m_be), .m_rdata(m_rdata), .m_ack(m_ack));
reg [15:0] ram [0:32767];
reg ack_r = 1'b0;
assign m_rdata = ram[m_addr[15:1]];
assign m_ack = ack_r;
integer i, wd, errors = 0;
always @(posedge clk) begin
    if (rst) ack_r <= 1'b0;
    else begin
        ack_r <= m_req && !ack_r;
        if (m_req && m_we && !ack_r) begin
            if (m_be[0]) ram[m_addr[15:1]][7:0]  <= m_wdata[7:0];
            if (m_be[1]) ram[m_addr[15:1]][15:8] <= m_wdata[15:8];
        end
    end
end
task automatic check(input condition, input [255:0] nm);
    if (condition !== 1'b1) begin errors = errors + 1; $display("  FAIL: %0s", nm); end
endtask
task automatic put_el(input integer a, input [15:0] v);
    if (a[0]) ram[a>>1][15:8] = v[7:0]; else ram[a>>1][7:0] = v[7:0];
    // high byte of a halfword element lands at a+1
    if (a[0]) ram[(a+1)>>1][7:0] = v[15:8]; else ram[a>>1][15:8] = v[15:8];
endtask
function [7:0] gb(input integer a);
    gb = a[0] ? ram[a>>1][15:8] : ram[a>>1][7:0];
endfunction
task automatic clear_ram; for (i=0;i<32768;i=i+1) ram[i] = 16'h0000; endtask
// Seed the CPU directly at S_STR_OP2 and let the string engine run to S_NEXT.
task automatic run_case(input [7:0] opb, input [7:0] sub,
                        input integer o1, input integer o2,
                        input integer l1, input integer l2, input [15:0] r26);
    @(negedge clk);
    rst = 1'b1; repeat(2) @(posedge clk); @(negedge clk);
    cpu.st = cpu.S_STR_OP2;
    cpu.cur_op = opb;
    cpu.subop  = sub;
    cpu.op1 = o1; cpu.op2 = o2;
    cpu.str_src = o1;    // S_STR_OP1 normally seeds this; we enter at S_STR_OP2
    cpu.str_dst = o2;
    cpu.str_len1 = l1;
    cpu.len1 = 0; cpu.len2 = 0;
    cpu.fb[3] = l2[7:0];
    cpu.r[26] = {16'b0, r26};
    cpu.dbus_req = 1'b0; cpu.dbus_we = 1'b0;
    rst = 1'b0;
    wd = 0;
    while ((cpu.st !== cpu.S_NEXT) && (wd < 4000)) begin @(posedge clk); #1; wd = wd + 1; end
    check(wd < 4000, "case completes");
endtask
